// ─── MULTI-INBOX CAPACITY ROUTER ───────────────────────────────────────────
//
// 1. Reads today's send count per inbox from Sent Log
// 2. Filters leads with status='ready'
// 3. Assigns each ready lead to an inbox that still has capacity
// 4. Enforces per-inbox daily cap (configurable below)
// 5. Returns only the leads that will be sent today, with inbox assigned

const MAX_PER_INBOX = 20; // Hard ceiling per Gmail account
const SEND_DAYS = ['Monday','Tuesday','Wednesday','Thursday','Friday'];
const today = new Date();
const todayStr = today.toISOString().split('T')[0];
const dayName = today.toLocaleDateString('en-US', { weekday: 'long' });

// Safety gate: do not run on weekends
if (!SEND_DAYS.includes(dayName)) {
  return [];
}

// ── Count today's sends per inbox from Sent Log ────────────────────────────
const sentLogItems = $('Read Sent Log (for today\'s count)').all();
const sentTodayByInbox = {};

for (const logItem of sentLogItems) {
  const log = logItem.json;
  const logDate = (log['Timestamp'] || '').split('T')[0];
  if (logDate !== todayStr) continue;
  if (log['Status'] !== 'sent') continue;
  const inbox = log['Inbox Used'] || 'inbox1';
  sentTodayByInbox[inbox] = (sentTodayByInbox[inbox] || 0) + 1;
}

// ── Get capacity remaining per inbox ──────────────────────────────────────
const inboxes = ['inbox1', 'inbox2', 'inbox3', 'inbox4', 'inbox5'];
const capacity = {};
for (const inbox of inboxes) {
  const sent = sentTodayByInbox[inbox] || 0;
  capacity[inbox] = Math.max(0, MAX_PER_INBOX - sent);
}

// ── Filter ready leads ─────────────────────────────────────────────────────
const allLeads = $('Read Leads (Leads Sheet)').all();
const readyLeads = allLeads.filter(item => {
  const lead = item.json;
  return lead['Status'] === 'ready'
    && lead['Email']
    && lead['Do Not Contact'] !== 'TRUE'
    && lead['Do Not Contact'] !== true
    && lead['Email Verified'] !== 'no';
});

// ── Assign leads to inboxes based on capacity ──────────────────────────────
const outputItems = [];
const usedCapacity = { ...Object.fromEntries(inboxes.map(i => [i, 0])) };

for (const leadItem of readyLeads) {
  const lead = leadItem.json;
  // Respect manually assigned inbox if set
  const preferredInbox = lead['Assigned Inbox'];

  let assignedInbox = null;

  if (preferredInbox && inboxes.includes(preferredInbox)) {
    const remaining = capacity[preferredInbox] - usedCapacity[preferredInbox];
    if (remaining > 0) {
      assignedInbox = preferredInbox;
    }
  } else {
    // Auto-assign: pick inbox with most remaining capacity
    const available = inboxes
      .filter(i => (capacity[i] - usedCapacity[i]) > 0)
      .sort((a, b) => (capacity[b] - usedCapacity[b]) - (capacity[a] - usedCapacity[a]));
    if (available.length > 0) {
      assignedInbox = available[0];
    }
  }

  if (!assignedInbox) break; // All inboxes at capacity for today

  usedCapacity[assignedInbox]++;
  outputItems.push({
    json: {
      ...lead,
      'Assigned Inbox': assignedInbox,
      _capacityLog: `Assigned to ${assignedInbox} (${usedCapacity[assignedInbox]}/${MAX_PER_INBOX})`
    }
  });
}

return outputItems;

// Build personalized email for each lead
// Template selection: clinic type × step
const items = $input.all();
const outputItems = [];

for (const item of items) {
  const lead = item.json;
  const clinicType = (lead['Clinic Type'] || 'dental').toLowerCase();
  const firstName = lead['First Name'] || lead['Contact Name'] || 'there';
  const businessName = lead['Business Name'] || 'your clinic';
  const city = lead['City'] || 'your area';
  const personTag = lead['Personalization Tag'] || 'a few areas worth discussing';

  let subject, body;

  if (clinicType === 'dental' || clinicType === 'orthodontics') {
    subject = `Quick question for ${firstName}`;
    body = `Hi ${firstName},\n\nI was looking at ${businessName} on Google Maps and noticed ${personTag} — I work with dental practices on exactly that.\n\nI help small dental offices attract more local patients without spending money on ads — usually through optimizing their Google Business profile and getting a steady flow of patient referrals set up systematically.\n\nMost practices I work with pick up 3–8 new patients/month within the first 60 days.\n\nWould a 15-minute call this week make sense to see if it's a fit?\n\n[YOUR NAME]\n[YOUR TITLE]\n[YOUR PHONE]\n\nYou're receiving this because ${businessName} appears in local dental searches for ${city}. Reply "unsubscribe" to never hear from me again.`;
  } else {
    subject = `Quick idea for ${businessName}`;
    body = `Hi ${firstName},\n\nI came across ${businessName} while researching aesthetic clinics in ${city} — ${personTag}.\n\nI work with small med spas and aesthetic practices on client retention and new patient acquisition — without paid ads. Specifically: getting existing clients to come back more often and refer friends automatically.\n\nThe average practice I work with adds $3–5K/month in recurring revenue within 90 days just from retention fixes.\n\nWould a quick 15-minute call make sense to see if there's a fit for your practice?\n\n[YOUR NAME]\n[YOUR TITLE]\n[YOUR PHONE]\n\nYou're receiving this because ${businessName} appears in local aesthetic searches for ${city}. Reply "unsubscribe" to never hear from me again.`;
  }

  outputItems.push({
    json: {
      ...lead,
      emailSubject: subject,
      emailBody: body
    }
  });
}

return outputItems;

// Add randomized human-like delay (180–480 seconds = 3–8 minutes)
// First item in the batch gets no delay; subsequent ones get spaced delays
const items = $input.all();
const outputItems = [];

for (let i = 0; i < items.length; i++) {
  const minDelay = 180000; // 3 minutes in ms
  const maxDelay = 480000; // 8 minutes in ms
  const delay = i === 0 ? 0 : Math.floor(Math.random() * (maxDelay - minDelay + 1)) + minDelay;

  outputItems.push({
    json: {
      ...items[i].json,
      _sendDelay: delay,
      _sendIndex: i + 1,
      _sendTotal: items.length
    }
  });
}

return outputItems;

// Merge outputs from all Gmail nodes and prepare the Sent Log entry
const item = $input.item.json;
const now = new Date().toISOString();

return [{
  json: {
    Timestamp: now,
    'Lead ID': item['Lead ID'],
    'Business Name': item['Business Name'],
    Email: item['Email'],
    Step: '1',
    'Inbox Used': item['Assigned Inbox'],
    Subject: item['emailSubject'],
    Status: 'sent'
  }
}];

// Update lead status in Leads sheet
const item = $input.item.json;
const today = new Date().toISOString().split('T')[0];
const next = new Date();
next.setDate(next.getDate() + 3);
const nextActionDate = next.toISOString().split('T')[0];

return [{
  json: {
    'Lead ID': item['Lead ID'] || item['Lead ID'],
    Status: 'emailed-step1',
    'Step 1 Sent Date': today,
    'Next Action Date': nextActionDate,
    'Assigned Inbox': item['Assigned Inbox']
  }
}];
